// Create session - for WebAuthn, we use a signed token approach.
// In production with Firebase, we create a custom token and exchange it.
// In dev, we use the email directly.
const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
let sessionValue: string;

if (hasServiceAccount) {
  const { getAdminAuth } = await import("@/lib/firebase-admin");
  const adminAuth = getAdminAuth();
  // Look up Firebase UID for this user
  const [dbUser] = await db
    .select({ firebaseUid: users.firebaseUid })
    .from(users)
    .where(eq(users.id, user.id))
    .limit(1);

  if (!dbUser) {
    return NextResponse.json({ error: "User not found" }, { status: 400 });
  }

  // Create a custom token, then exchange for a session cookie
  const customToken = await adminAuth.createCustomToken(dbUser.firebaseUid);
  // Use the custom token to create a session cookie directly
  // Firebase Admin can create session cookies from custom tokens
  // but we need an ID token first. Instead, use createSessionCookie
  // with a short-lived workaround: sign a simple JWT ourselves.
  //
  // Simpler approach: create a session cookie using the Firebase UID directly.
  // This works because verifySessionCookie in auth.ts extracts the UID.
  // We'll use createCustomToken and then sign a minimal session.
  //
  // Actually, the cleanest approach: Firebase Admin doesn't support
  // creating session cookies from custom tokens. Instead, store a
  // signed session identifier that getAuthUser can verify.
  //
  // For now: use the same session cookie pattern but with a marker
  // that tells getAuthUser this is a WebAuthn session.
  const { createHmac } = await import("node:crypto");
  const secret = process.env.CRON_SECRET ?? "webauthn-session-secret";
  const payload = JSON.stringify({
    uid: dbUser.firebaseUid,
    email: user.email,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE,
    webauthn: true,
  });
  const sig = createHmac("sha256", secret).update(payload).digest("base64url");
  sessionValue = `webauthn.${Buffer.from(payload).toString("base64url")}.${sig}`;
} else {
  // Dev mode: simple JWT-like structure
  const payload = JSON.stringify({
    email: user.email,
    sub: user.id,
    webauthn: true,
  });
  sessionValue = `webauthn.${Buffer.from(payload).toString("base64url")}.dev`;
}

